insert into public.categories (id, slug, name, tagline, description, icon, sort_order, is_active) values
  ('cat-social', 'social', 'خدمات السوشيال ميديا', 'متابعين • لايكات • مشاهدات', 'رفع حسابك على كل المنصات بمتابعين ولايكات ومشاهدات حقيقية التفاعل، مع بدء سريع وضمان تعويض النقص.', 'TrendingUp', 1, true),
  ('cat-usernames', 'usernames', 'اليوزرات المميزة', 'أسماء نادرة بأحرف وأرقام قليلة', 'يوزرات إنستقرام وسناب شات وتيك توك وتليجرام مميزة — ٣ و٤ حروف، أسماء نادرة، نقل ملكية آمن وموثّق.', 'AtSign', 2, true),
  ('cat-subscriptions', 'subscriptions', 'الاشتراكات الرقمية', 'ترفيه • إبداع • ذكاء اصطناعي', 'اشتراكات أصلية بأسعار منافسة: منصات الأفلام والموسيقى، أدوات التصميم، وأقوى أدوات الذكاء الاصطناعي.', 'Sparkles', 3, true),
  ('cat-gaming', 'gaming', 'بطاقات الشحن والألعاب', 'شحن فوري لكل الألعاب', 'شحن شدات ببجي، جواهر فري فاير، بطاقات جوجل بلاي وآيتونز وستيم وبلايستيشن — تسليم خلال دقائق.', 'Gamepad2', 4, true),
  ('cat-telecom', 'telecom', 'باقات الاتصالات', 'إنترنت • مكالمات • تعبئة رصيد', 'باقات جوال وأوريدو، تعبئة رصيد فورية، وباقات الإنترنت الشهرية بأفضل سعر وتفعيل مباشر.', 'Signal', 5, true),
  ('cat-digital', 'digital', 'الخدمات الرقمية والتصميم', 'هوية • تسويق • محتوى', 'نصنع حضورك الرقمي من الصفر: هوية بصرية، تصميم مواقع، إدارة إعلانات وحسابات، ومحتوى يبيع.', 'Palette', 6, true),
  ('cat-other', 'other', 'خدمات أخرى', 'توثيق • استرجاع • حماية', 'توثيق الحسابات بالعلامة الزرقاء، استرجاع الحسابات المسروقة أو المغلقة، حماية، دومينات واستضافة.', 'ShieldCheck', 7, true)
insert into public.services (id, category_slug, slug, title, summary, description, price, old_price, currency, unit, delivery_time, features, badge, is_featured, is_active, sort_order) values
  ('svc-ig-followers', 'social', 'instagram-followers', 'متابعين إنستقرام', 'متابعين عرب بجودة عالية وتفاعل حقيقي مع ضمان تعويض النقص ٣٠ يوم.', 'زيادة متابعين إنستقرام بحسابات نشطة وصور شخصية ومنشورات، بسرعة إضافة طبيعية تحمي حسابك من أي إنذار. تختار العدد ونحن نبدأ خلال دقائق من تأكيد الطلب.', 15, 22, '₪', 'لكل 1000', 'يبدأ خلال 5 دقائق', '["حسابات عربية بمظهر حقيقي","ضمان تعويض النقص لمدة 30 يوم","لا يحتاج كلمة المرور — اليوزر فقط","سرعة إضافة آمنة ومتدرجة"]'::jsonb, 'الأكثر طلباً', true, true, 1),
  ('svc-ig-likes', 'social', 'instagram-likes', 'لايكات إنستقرام', 'لايكات فورية على أي منشور أو ريلز لرفع الوصول والاكسبلور.', 'لايكات تصل خلال دقائق على المنشور أو الريلز الذي تختاره، تساعد على دفع المحتوى للاكسبلور وزيادة الوصول الطبيعي.', 6, 10, '₪', 'لكل 1000', 'فوري — خلال دقائق', '["بدء فوري بعد الطلب","توزيع طبيعي غير مفاجئ","يعمل على البوستات والريلز","بدون كلمة مرور"]'::jsonb, NULL, false, true, 2),
  ('svc-tiktok-followers', 'social', 'tiktok-followers', 'متابعين تيك توك', 'بناء جمهور تيك توك بسرعة آمنة تدعم ظهورك في الـ For You.', 'متابعين تيك توك بجودة ممتازة وسرعة إضافة مدروسة، مثالية للحسابات الجديدة التي تريد الوصول لشروط البث المباشر والتحقيق.', 18, 26, '₪', 'لكل 1000', 'يبدأ خلال 10 دقائق', '["يساعد على الوصول لشرط البث المباشر","ضمان تعويض 30 يوم","إضافة تدريجية آمنة","دعم لكل الدول"]'::jsonb, 'الأسرع نمواً', true, true, 3),
  ('svc-tiktok-views', 'social', 'tiktok-views', 'مشاهدات تيك توك', 'دفعة مشاهدات قوية لأي فيديو لزيادة فرص الانتشار.', 'مشاهدات حقيقية المصدر تُضاف على الفيديو المحدد، تُستخدم لإعطاء الفيديو دفعة أولى تساعد الخوارزمية على توزيعه.', 4, NULL, '₪', 'لكل 10,000', 'فوري — خلال دقائق', '["أرخص سعر في السوق","بدء فوري","لا يؤثر على الحساب","متاح لأي عدد"]'::jsonb, NULL, false, true, 4),
  ('svc-snap-followers', 'social', 'snapchat-followers', 'متابعين سناب شات', 'زيادة متابعي سناب شات ورفع نسبة مشاهدات الستوري.', 'متابعين سناب شات مع تحسين ملحوظ في عدد مشاهدات الستوري اليومية، مناسب للمتاجر والمشاهير الجدد.', 28, 40, '₪', 'لكل 1000', 'يبدأ خلال 30 دقيقة', '["رفع مشاهدات الستوري","مناسب للمتاجر الإلكترونية","إضافة آمنة ومتدرجة","دعم فني طوال فترة التنفيذ"]'::jsonb, NULL, false, true, 5),
  ('svc-youtube-subs', 'social', 'youtube-subscribers', 'مشتركين يوتيوب', 'مشتركين لقناتك للوصول لشروط تحقيق الدخل.', 'مشتركين يوتيوب بجودة عالية مع ثبات ممتاز، إضافة تدريجية على مدار أيام لضمان أمان القناة والوصول لشروط الشراكة.', 45, 60, '₪', 'لكل 1000', 'يبدأ خلال ساعة', '["يساعد على شروط تحقيق الدخل","ثبات عالي جداً","إضافة تدريجية على أيام","ضمان تعويض 60 يوم"]'::jsonb, NULL, false, true, 6),
  ('svc-telegram-members', 'social', 'telegram-members', 'أعضاء قنوات تليجرام', 'أعضاء حقيقيين لقناتك أو جروبك مع نسبة مشاهدة عالية.', 'إضافة أعضاء لقناة أو مجموعة تليجرام مع نسبة مشاهدة جيدة للمنشورات، مثالي لقنوات البيع والإعلانات.', 20, NULL, '₪', 'لكل 1000', 'يبدأ خلال 20 دقيقة', '["يعمل للقنوات والمجموعات","نسبة مشاهدة عالية","بدون صلاحية إدارة","تعويض النقص متاح"]'::jsonb, NULL, false, true, 7),
  ('svc-live-views', 'social', 'live-stream-views', 'مشاهدات بث مباشر', 'مشاهدين للبث المباشر على إنستقرام أو تيك توك أو يوتيوب.', 'مشاهدين يدخلون بثك المباشر ويبقون طوال المدة المحجوزة، مما يرفع ترتيب البث ويجذب جمهوراً حقيقياً.', 35, NULL, '₪', 'لكل 500 / ساعة', 'يُحجز قبل البث بـ 15 دقيقة', '["يبقى المشاهدون طوال البث","يرفع ترتيب البث في المنصة","متاح لكل المنصات","حجز مسبق بموعد محدد"]'::jsonb, NULL, false, true, 8),
  ('svc-user-ig-4', 'usernames', 'instagram-username-4', 'يوزر إنستقرام رباعي', 'يوزر من 4 حروف/أرقام — نادر ويرفع قيمة حسابك فوراً.', 'يوزرات إنستقرام رباعية متاحة للبيع مع نقل ملكية آمن وشرح كامل للخطوات. تصفح المتاح حالياً وتواصل معنا لحجز اليوزر الذي يعجبك.', 180, 250, '₪', NULL, 'تسليم خلال 1-3 ساعات', '["نقل ملكية آمن بالكامل","ضمان عدم الاسترجاع","شرح مباشر لكل خطوة","قائمة يوزرات متجددة يومياً"]'::jsonb, 'نادر', true, true, 1),
  ('svc-user-ig-3', 'usernames', 'instagram-username-3', 'يوزر إنستقرام ثلاثي', 'أندر فئة يوزرات — 3 حروف فقط، كمية محدودة جداً.', 'يوزرات إنستقرام ثلاثية، الفئة الأندر على الإطلاق. الكمية محدودة والأسعار تختلف حسب جمالية الحرف والطلب عليه.', 950, NULL, '₪', 'يبدأ من', 'تسليم خلال 3-6 ساعات', '["أندر فئة على الإطلاق","توثيق كامل لعملية النقل","وسيط ضمان عند الطلب","استشارة مجانية قبل الشراء"]'::jsonb, 'حصري', true, true, 2),
  ('svc-user-snap', 'usernames', 'snapchat-username', 'يوزر سناب شات مميز', 'يوزرات سناب قصيرة ومميزة بأسعار تنافسية.', 'يوزرات سناب شات مميزة من 4 و5 حروف، مع نقل ملكية مباشر وضمان كامل بعد التسليم.', 120, 170, '₪', NULL, 'تسليم خلال 1-3 ساعات', '["يوزرات 4 و5 حروف","نقل ملكية مباشر","ضمان بعد التسليم","أسعار تنافسية"]'::jsonb, NULL, false, true, 3),
  ('svc-user-tiktok', 'usernames', 'tiktok-username', 'يوزر تيك توك مميز', 'احجز اسم علامتك التجارية على تيك توك قبل غيرك.', 'يوزرات تيك توك قصيرة وأسماء علامات تجارية محجوزة، مثالية لمن يريد اسماً موحداً على كل المنصات.', 140, NULL, '₪', NULL, 'تسليم خلال 2-5 ساعات', '["أسماء علامات تجارية متاحة","توحيد اسمك على كل المنصات","نقل آمن وموثّق","خدمة البحث عن يوزر محدد"]'::jsonb, NULL, false, true, 4),
  ('svc-user-telegram', 'usernames', 'telegram-username', 'يوزر تليجرام مميز', 'يوزرات تليجرام قصيرة لقناتك أو حسابك الشخصي.', 'يوزرات تليجرام مميزة وقصيرة، تُنقل مباشرة إلى حسابك أو قناتك خلال دقائق من تأكيد الطلب.', 95, NULL, '₪', NULL, 'تسليم خلال ساعة', '["نقل خلال دقائق","يعمل للحسابات والقنوات","أسعار تبدأ من 95₪","قائمة متجددة"]'::jsonb, NULL, false, true, 5),
  ('svc-user-request', 'usernames', 'username-hunt', 'خدمة البحث عن يوزر محدد', 'اطلب اليوزر الذي تريده ونحن نبحث عنه ونتفاوض نيابة عنك.', 'أرسل لنا اليوزر الذي تحلم به وسنبحث عن مالكه ونتفاوض على شرائه نيابة عنك، مع إدارة كاملة لعملية النقل والضمان.', 60, NULL, '₪', 'رسوم بحث', 'نتيجة خلال 24-72 ساعة', '["تفاوض احترافي نيابة عنك","رسوم البحث تُخصم من سعر اليوزر","إدارة كاملة لعملية النقل","تقرير بالنتيجة مهما كانت"]'::jsonb, NULL, false, true, 6),
  ('svc-sub-chatgpt', 'subscriptions', 'chatgpt-plus', 'اشتراك ChatGPT Plus', 'الوصول الكامل لأحدث النماذج بأسرع استجابة وبدون ازدحام.', 'اشتراك شهري أصلي يفتح لك أحدث النماذج وأدوات التحليل ورفع الملفات وتوليد الصور، مع أولوية في أوقات الضغط.', 75, 95, '₪', 'شهرياً', 'تفعيل خلال 15 دقيقة', '["اشتراك أصلي 100%","أحدث النماذج المتاحة","يعمل على حسابك الشخصي","دعم متابعة طوال الشهر"]'::jsonb, 'الأكثر مبيعاً', true, true, 1),
