  ('svc-game-steam', 'gaming', 'steam-wallet', 'بطاقات ستيم Steam', 'رصيد محفظة ستيم لشراء أي لعبة على المنصة.', 'أكواد شحن محفظة Steam بكل الفئات، تُضاف لحسابك مباشرة وتستخدمها لشراء أي لعبة أو عنصر داخل المنصة.', 42, NULL, '₪', 'فئة 10$', 'الكود خلال 15 دقيقة', '["أكواد أصلية","كل الفئات متوفرة","تُضاف للمحفظة مباشرة","ضمان تفعيل"]'::jsonb, NULL, false, true, 6),
