  ('svc-game-roblox', 'gaming', 'roblox-robux', 'شحن روبلوكس Robux', 'روبكس لحسابك في روبلوكس بشحن آمن ومباشر.', 'شحن Robux لحساب روبلوكس الخاص بك بطريقة آمنة، مع كل الفئات المتاحة وتسليم سريع.', 20, NULL, '₪', '400 روبكس', 'شحن خلال 30 دقيقة', '["شحن آمن للحساب","كل الفئات","أسعار تنافسية","دعم فني"]'::jsonb, NULL, false, true, 8),
  ('svc-tel-sawa-post', 'telecom', 'sawa-post-plus', 'باقة سوا بوست بلس', 'إنترنت ومكالمات بباقة شهرية متكاملة وتفعيل فوري.', 'باقة سوا بوست بلس الشهرية تشمل إنترنت ومكالمات ورسائل، تُفعّل مباشرة على رقمك خلال دقائق من تأكيد الطلب.', 55, 70, '₪', 'شهرياً', 'تفعيل خلال 10 دقائق', '["إنترنت ومكالمات ورسائل","تفعيل مباشر على رقمك","بدون عقود أو التزام","تذكير قبل انتهاء الباقة"]'::jsonb, 'مميزة', true, true, 1),
  ('svc-tel-jawwal-net', 'telecom', 'jawwal-internet', 'باقات إنترنت جوال', 'باقات نت يومية وأسبوعية وشهرية بكل الأحجام.', 'كل باقات الإنترنت من جوال — يومية، أسبوعية وشهرية — بأحجام مختلفة تناسب استخدامك، مع تفعيل فوري.', 15, NULL, '₪', 'تبدأ من', 'تفعيل خلال 10 دقائق', '["باقات يومية وأسبوعية وشهرية","كل الأحجام متوفرة","تفعيل فوري","استشارة لاختيار الأنسب"]'::jsonb, NULL, false, true, 2),
  ('svc-tel-ooredoo', 'telecom', 'ooredoo-packages', 'باقات أوريدو', 'كل باقات أوريدو للإنترنت والمكالمات بتفعيل مباشر.', 'باقات أوريدو المتنوعة للإنترنت والمكالمات، نساعدك في اختيار الباقة الأنسب لاستخدامك ونفعّلها لك مباشرة.', 20, NULL, '₪', 'تبدأ من', 'تفعيل خلال 10 دقائق', '["كل الباقات متوفرة","تفعيل مباشر","استشارة مجانية","أسعار المشغّل"]'::jsonb, NULL, false, true, 3),
  ('svc-tel-topup', 'telecom', 'mobile-topup', 'تعبئة رصيد فورية', 'تعبئة رصيد لأي شبكة بأي مبلغ خلال دقائق.', 'تعبئة رصيد فورية لأي شبكة وبأي مبلغ تريده، أرسل الرقم والمبلغ ونحن نتكفل بالباقي.', 10, NULL, '₪', 'تبدأ من', 'تعبئة خلال 5 دقائق', '["كل الشبكات","أي مبلغ تريده","تعبئة فورية","متاح 24 ساعة"]'::jsonb, NULL, false, true, 4),
  ('svc-tel-esim', 'telecom', 'travel-esim', 'شرائح eSIM للسفر', 'إنترنت أثناء السفر بدون شريحة فعلية أو تجوال باهظ.', 'شرائح eSIM رقمية تعمل في أكثر من 100 دولة، تُفعّل بمسح كود QR وتوفر عليك رسوم التجوال المرتفعة.', 45, NULL, '₪', 'تبدأ من', 'الكود خلال 30 دقيقة', '["أكثر من 100 دولة","تفعيل بمسح QR","بدون شريحة فعلية","خطط بأحجام مختلفة"]'::jsonb, 'جديد', false, true, 5),
  ('svc-dig-brand', 'digital', 'brand-identity', 'تصميم هوية بصرية كاملة', 'لوقو + دليل ألوان وخطوط + تطبيقات جاهزة للطباعة والنشر.', 'هوية بصرية متكاملة تبدأ من فهم نشاطك وجمهورك: شعار احترافي بعدة صيغ، نظام ألوان وخطوط، نمط بصري خاص، وتطبيقات جاهزة (كرت شخصي، أيقونة، أغلفة سوشيال ميديا).', 650, 900, '₪', 'تبدأ من', 'التسليم خلال 5-7 أيام', '["شعار احترافي بعدة صيغ وملفات مفتوحة","دليل هوية كامل (ألوان، خطوط، استخدامات)","تطبيقات جاهزة للطباعة والنشر","تعديلات غير محدودة حتى الرضا"]'::jsonb, 'الأكثر تميزاً', true, true, 1),
  ('svc-dig-website', 'digital', 'website-design', 'تصميم وتطوير موقع إلكتروني', 'موقع سريع ومتجاوب يحوّل الزائر إلى عميل فعلي.', 'موقع إلكتروني احترافي مبني بأحدث التقنيات: سريع، متجاوب مع كل الشاشات، مهيأ لمحركات البحث، ومربوط بقاعدة بيانات ولوحة تحكم تديرها بنفسك.', 1200, NULL, '₪', 'تبدأ من', 'التسليم خلال 10-20 يوم', '["تصميم متجاوب مع كل الأجهزة","تهيئة كاملة لمحركات البحث SEO","لوحة تحكم لإدارة المحتوى","ربط واتساب ودفع وتحليلات"]'::jsonb, NULL, true, true, 2),
  ('svc-dig-ads', 'digital', 'ads-management', 'إدارة الحملات الإعلانية', 'إعلانات ممولة مدروسة تجيب نتائج حقيقية لا مجرد مشاهدات.', 'إدارة حملاتك المموّلة على إنستقرام وفيسبوك وتيك توك: استهداف دقيق، تصاميم إعلانية جذابة، اختبار مستمر وتقارير أسبوعية توضح العائد على كل شيكل.', 450, NULL, '₪', 'شهرياً', 'انطلاق الحملة خلال 48 ساعة', '["استهداف دقيق حسب جمهورك","تصاميم إعلانية احترافية","تحسين مستمر واختبار A/B","تقرير أسبوعي واضح بالنتائج"]'::jsonb, NULL, false, true, 3),
  ('svc-dig-content', 'digital', 'content-management', 'إدارة حسابات ومحتوى', 'خطة محتوى شهرية + تصاميم + نشر + تفاعل مع الجمهور.', 'نتولى حساباتك بالكامل: خطة محتوى شهرية مبنية على أهدافك، تصاميم ونصوص، جدولة ونشر، والرد على التعليقات والرسائل.', 550, 750, '₪', 'شهرياً', 'بداية العمل خلال 3 أيام', '["خطة محتوى شهرية مكتوبة","16 تصميم + نصوص شهرياً","جدولة ونشر منتظم","إدارة التعليقات والرسائل"]'::jsonb, NULL, false, true, 4),
  ('svc-dig-logo', 'digital', 'logo-design', 'تصميم شعار احترافي', 'شعار مميز بعدة مقترحات وملفات مفتوحة بجودة لا نهائية.', 'تصميم شعار احترافي يبدأ بثلاثة مقترحات مختلفة، تختار منها ونطوّره حتى الشكل النهائي، مع تسليم كل الصيغ والملفات المفتوحة.', 250, 350, '₪', NULL, 'التسليم خلال 3-5 أيام', '["3 مقترحات مختلفة","تعديلات حتى الرضا التام","كل الصيغ (PNG, SVG, PDF, AI)","نسخ ملونة وأحادية اللون"]'::jsonb, NULL, false, true, 5),
  ('svc-dig-video', 'digital', 'video-editing', 'مونتاج فيديو وريلز', 'ريلز وإعلانات بمونتاج سريع الإيقاع يوقف السكرول.', 'مونتاج احترافي للريلز والإعلانات القصيرة: قص سريع الإيقاع، مؤثرات، موسيقى، ترجمة وحركة نصوص تجذب الانتباه في أول ثانيتين.', 120, NULL, '₪', 'للفيديو', 'التسليم خلال 48 ساعة', '["مونتاج سريع الإيقاع","ترجمة وحركة نصوص","موسيقى ومؤثرات","جولتا تعديل مجانيتان"]'::jsonb, NULL, false, true, 6),
  ('svc-dig-store', 'digital', 'online-store', 'إنشاء متجر إلكتروني', 'متجر متكامل بسلة ودفع ولوحة تحكم وربط واتساب.', 'متجر إلكتروني جاهز للبيع من اليوم الأول: عرض منتجات، سلة شراء، طرق دفع، إدارة طلبات، وربط مباشر بالواتساب لتحويل الزوار إلى طلبات.', 1800, NULL, '₪', 'تبدأ من', 'التسليم خلال 14-21 يوم', '["سلة شراء وإدارة طلبات","ربط واتساب وطرق الدفع","لوحة تحكم كاملة","تدريب على الاستخدام"]'::jsonb, NULL, false, true, 7),
  ('svc-oth-verify', 'other', 'account-verification', 'توثيق الحسابات', 'العلامة الزرقاء لحسابك على إنستقرام أو تيك توك أو فيسبوك.', 'خدمة توثيق الحسابات بالعلامة الزرقاء عبر تجهيز ملف الحساب والمستندات وتقديم الطلب بالطريقة الصحيحة لرفع فرص القبول.', 900, NULL, '₪', 'تبدأ من', 'المدة 7-21 يوم', '["تجهيز كامل لملف الحساب","مراجعة المستندات قبل التقديم","متابعة الطلب حتى النتيجة","استشارة مجانية قبل البدء"]'::jsonb, NULL, false, true, 1),
  ('svc-oth-recovery', 'other', 'account-recovery', 'استرجاع الحسابات', 'استرجاع الحسابات المسروقة أو المغلقة أو المنسية.', 'خدمة استرجاع الحسابات المخترقة أو المغلقة أو التي فقدت الوصول إليها، بطرق رسمية مع متابعة الطلب حتى استعادة الحساب.', 150, NULL, '₪', 'تبدأ من', 'المدة 1-7 أيام', '["طرق رسمية وآمنة","يشمل الحسابات المخترقة والمغلقة","متابعة حتى النتيجة","لا تدفع إلا عند النجاح"]'::jsonb, 'مضمون', true, true, 2),
  ('svc-oth-security', 'other', 'account-security', 'حماية وتأمين الحسابات', 'إقفال حسابك أمام محاولات الاختراق قبل ما تصير المشكلة.', 'مراجعة أمنية شاملة لحساباتك: تفعيل التحقق بخطوتين، مراجعة الجلسات والتطبيقات المرتبطة، تقوية كلمات المرور وإعداد خطة استرجاع.', 80, NULL, '₪', 'للحساب', 'التنفيذ خلال ساعتين', '["تفعيل التحقق بخطوتين","مراجعة الجلسات والتطبيقات","خطة استرجاع جاهزة","تقرير أمني مبسّط"]'::jsonb, NULL, false, true, 3),
  ('svc-oth-domain', 'other', 'domain-hosting', 'دومين واستضافة', 'حجز اسم النطاق واستضافة سريعة مع إعداد كامل.', 'حجز اسم النطاق المناسب لنشاطك مع استضافة سريعة وشهادة SSL وإيميلات باسم موقعك، وإعداد كامل جاهز للانطلاق.', 180, NULL, '₪', 'سنوياً', 'الإعداد خلال 24 ساعة', '["دومين + استضافة + SSL","إيميلات باسم موقعك","إعداد كامل جاهز","دعم التجديد السنوي"]'::jsonb, NULL, false, true, 4),
  ('svc-oth-vpn', 'other', 'vpn-subscription', 'اشتراك VPN', 'تصفح آمن وسريع مع سيرفرات في كل دول العالم.', 'اشتراك VPN موثوق بسرعات عالية وسيرفرات في عشرات الدول، يعمل على كل الأجهزة مع حماية كاملة للخصوصية.', 35, 50, '₪', 'سنوياً', 'تفعيل خلال 15 دقيقة', '["سيرفرات في عشرات الدول","يعمل على كل الأجهزة","سرعات عالية","بدون تسجيل نشاط"]'::jsonb, NULL, false, true, 5),
  ('svc-oth-consult', 'other', 'digital-consultation', 'استشارة رقمية', 'جلسة مباشرة نضع فيها خطة واضحة لحضورك الرقمي.', 'جلسة استشارية مباشرة نراجع فيها وضعك الحالي ونضع خطة عملية واضحة: من أين تبدأ، على أي منصة تركز، وما الميزانية المطلوبة.', 100, NULL, '₪', 'للجلسة', 'حجز خلال 24 ساعة', '["جلسة 60 دقيقة مباشرة","تحليل وضعك الحالي","خطة عملية مكتوبة","قيمة الجلسة تُخصم عند التعاقد"]'::jsonb, NULL, false, true, 6)
insert into public.testimonials (id, name, handle, rating, body, is_active, sort_order) values
  ('t1', 'محمود أبو ندى', 'صاحب متجر ملابس', 5, 'طلبت متابعين وباقة إدارة محتوى، خلال شهر صار عندي طلبات يومية من الإنستقرام. التعامل محترم والتسليم بوقته بالضبط.', true, 1),
  ('t2', 'سُلاف حرب', 'مصممة أزياء', 5, 'الهوية البصرية اللي عملولي غيّرت شكل مشروعي تماماً. حسّيت إنهم فهموا الفكرة أكثر مني.', true, 2),
  ('t3', 'أحمد ياسين', 'لاعب ومنشئ محتوى', 5, 'أشحن شدات من عندهم من سنة تقريباً. أرخص سعر لقيته والشحن ما تأخر ولا مرة وحدة.', true, 3),
  ('t4', 'رنا الأغا', 'صاحبة مشروع حلويات', 5, 'أخذت يوزر رباعي للحساب وكانت العملية مرتبة وواضحة من أولها لآخرها. ثقة من أول تعامل.', true, 4),
  ('t5', 'كريم دولة', 'مدير تسويق', 5, 'أفضل شي فيهم إنهم بيردوا بسرعة على الواتساب. سألت عشرين سؤال قبل ما أطلب وما زهقوا.', true, 5),
  ('t6', 'ليان مقداد', 'طالبة جامعية', 5, 'اشتركت كانفا برو وشات جي بي تي منهم، اشتغلوا من أول دقيقة وبنص السعر اللي كنت رح أدفعه.', true, 6)
